// Mon Coach — recettes (partie 5/6), portées depuis l'app Firebase/Vercel d'origine.
const RECIPES_PART5 = [
  {n:"Risotto crémeux aux champignons de Paris", cat:"déjeuner/dîner", tags:["classique"], kcal:480, p:14, c:68, f:16, prep:40, ing:["riz arborio","champignons de Paris","oignon","bouillon de légumes","parmesan","beurre"], qty:["250 g","300 g","1","1 L","50 g","30 g"], steps:["Faites revenir l'oignon émincé dans un peu de beurre, ajoutez le riz et faites-le nacrer 2 min.","Versez le bouillon chaud louche par louche en remuant régulièrement, sans jamais laisser le riz s'assécher, pendant 18 à 20 min.","Faites revenir les champignons émincés à la poêle à part et incorporez-les en fin de cuisson.","Hors du feu, ajoutez le parmesan et un peu de beurre pour lier le risotto, servez aussitôt."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Lasagnes bolognaise", cat:"déjeuner/dîner", tags:["classique"], kcal:620, p:32, c:55, f:28, prep:60, ing:["plaques de lasagne","bœuf haché","sauce tomate","béchamel","oignon","parmesan"], qty:["12 plaques","350 g","400 ml","500 ml","1","50 g"], steps:["Préparez une sauce bolognaise en faisant revenir l'oignon puis le bœuf haché, ajoutez la sauce tomate et laissez mijoter 20 min.","Préchauffez le four à 190°C. Dans un plat, alternez couches de plaques de lasagne, sauce bolognaise et béchamel.","Terminez par une couche de béchamel généreusement parsemée de parmesan.","Enfournez 35 à 40 min jusqu'à ce que le dessus soit bien doré et gratiné."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Poulet basquaise", cat:"déjeuner/dîner", tags:["classique"], kcal:460, p:38, c:26, f:20, prep:55, ing:["cuisses de poulet","poivrons","tomates","oignon","ail","riz"], qty:["4","3 (rouge, vert, jaune)","3","1","2 gousses","150 g (poids cru)"], steps:["Faites dorer les cuisses de poulet dans une cocotte, réservez.","Faites revenir l'oignon, l'ail et les poivrons émincés dans la même cocotte, ajoutez les tomates concassées.","Remettez le poulet dans la cocotte, couvrez et laissez mijoter 35 à 40 min jusqu'à ce que la viande soit bien tendre.","Servez avec du riz cuit à l'eau bouillante salée."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Choucroute garnie", cat:"déjeuner/dîner", tags:["classique"], kcal:640, p:32, c:30, f:42, prep:70, ing:["choucroute crue","saucisses fumées","lard fumé","pommes de terre","vin blanc","genièvre"], qty:["800 g","4","200 g","500 g","200 ml","quelques baies"], steps:["Rincez la choucroute et pressez-la légèrement, disposez-la dans une grande cocotte avec le lard et les baies de genièvre.","Ajoutez le vin blanc, couvrez et laissez mijoter à feu doux 1 h à 1 h 30.","20 min avant la fin, ajoutez les pommes de terre épluchées et les saucisses sur le dessus pour les réchauffer en même temps.","Servez bien chaud, la choucroute accompagnée des saucisses, du lard et des pommes de terre."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Pot-au-feu", cat:"déjeuner/dîner", tags:["classique"], kcal:480, p:36, c:28, f:22, prep:150, ing:["bœuf à braiser","carottes","poireaux","navets","oignon clouté","céleri"], qty:["800 g","4","3","3","1","2 branches"], steps:["Plongez la viande dans une grande cocotte d'eau froide, portez à ébullition et écumez.","Ajoutez l'oignon clouté et laissez mijoter à couvert 1 h 30 à feu doux.","Ajoutez les légumes épluchés et coupés en gros morceaux, poursuivez la cuisson 45 min à 1 h jusqu'à ce que tout soit bien tendre.","Servez la viande et les légumes bien chauds, avec un peu de bouillon et de la moutarde à côté."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Cassoulet maison", cat:"déjeuner/dîner", tags:["classique"], kcal:620, p:34, c:48, f:30, prep:90, ing:["haricots blancs","saucisses de Toulouse","poitrine de porc","oignon","ail","tomates concassées"], qty:["500 g (cuits)","4","200 g","1","2 gousses","200 g"], steps:["Faites revenir la poitrine de porc coupée en morceaux et les saucisses dans une cocotte.","Ajoutez l'oignon et l'ail émincés, les tomates concassées et les haricots blancs, mélangez.","Couvrez d'eau à hauteur, laissez mijoter à couvert 1 h à 1 h 15 à feu doux en remuant de temps en temps.","En fin de cuisson, laissez réduire à découvert 10 à 15 min jusqu'à ce que la sauce nappe bien les haricots."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Moules-frites", cat:"déjeuner/dîner", tags:["classique"], kcal:560, p:34, c:48, f:22, prep:35, ing:["moules","pommes de terre","vin blanc","échalote","crème fraîche","persil"], qty:["1,5 kg","600 g","150 ml","2","100 ml","1 bouquet"], steps:["Épluchez et coupez les pommes de terre en frites, faites-les cuire jusqu'à ce qu'elles soient dorées et croustillantes.","Nettoyez soigneusement les moules à l'eau froide et retirez celles qui restent ouvertes.","Faites revenir l'échalote émincée, ajoutez le vin blanc et les moules, couvrez et laissez cuire 5 à 7 min en remuant jusqu'à ce qu'elles soient toutes ouvertes.","Ajoutez la crème fraîche et le persil ciselé, mélangez et servez avec les frites."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Sandwich jambon-beurre", cat:"collation", tags:["classique"], kcal:380, p:16, c:40, f:16, prep:5, ing:["baguette","jambon blanc","beurre","cornichons"], qty:["1/2 baguette","2 tranches","20 g","quelques-uns"], steps:["Fendez la demi-baguette en deux dans la longueur.","Tartinez de beurre puis garnissez de jambon et de cornichons.","Refermez et dégustez aussitôt, ou emportez pour plus tard."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Tartine avocat & jambon", cat:"collation", tags:["classique"], kcal:320, p:14, c:26, f:18, prep:8, ing:["pain de campagne","avocat","jambon blanc","citron"], qty:["2 tranches","1","2 tranches","1/4"], steps:["Faites griller ou toastez légèrement le pain.","Écrasez l'avocat à la fourchette avec un filet de jus de citron, salez et poivrez.","Étalez sur les tartines et déposez le jambon par-dessus."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Wrap poulet & crudités", cat:"collation", tags:["classique"], kcal:360, p:22, c:34, f:14, prep:15, ing:["tortillas de blé","blanc de poulet","salade","tomate","carotte","sauce fromage blanc"], qty:["2","150 g","quelques feuilles","1","1","2 c. à soupe"], steps:["Faites cuire le blanc de poulet à la poêle 8 à 10 min, puis émincez-le.","Râpez la carotte, lavez la salade et coupez la tomate en fines lamelles.","Garnissez chaque tortilla de sauce, de poulet et de crudités, roulez bien serré et coupez en deux avant de servir."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Mini quiches maison", cat:"collation", tags:["classique"], kcal:280, p:10, c:18, f:18, prep:30, ing:["pâte brisée","œufs","crème liquide","lardons","emmental râpé"], qty:["1 rouleau","2","100 ml","80 g","40 g"], steps:["Préchauffez le four à 190°C. Découpez la pâte brisée à l'emporte-pièce et foncez des moules à mini-muffins.","Fouettez les œufs avec la crème, salez et poivrez, ajoutez les lardons et l'emmental.","Répartissez la préparation dans les moules et enfournez 15 à 18 min jusqu'à ce que les mini-quiches soient dorées."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Pain d'épices maison", cat:"collation", tags:["classique"], kcal:300, p:5, c:50, f:8, prep:45, ing:["farine de seigle","miel","lait","œuf","épices pain d'épices","levure chimique"], qty:["250 g","150 g","150 ml","1","2 c. à café","1 sachet"], steps:["Préchauffez le four à 160°C. Faites tiédir le miel avec le lait sans faire bouillir.","Mélangez la farine, les épices et la levure, ajoutez l'œuf puis le mélange miel-lait, fouettez jusqu'à obtenir une pâte lisse.","Versez dans un moule à cake chemisé et faites cuire 45 à 50 min jusqu'à ce qu'un couteau planté ressorte sec."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Milkshake banane maison", cat:"collation", tags:["classique"], kcal:280, p:8, c:40, f:9, prep:8, ing:["banane","lait","glace vanille","miel"], qty:["2","300 ml","2 boules","1 c. à soupe"], steps:["Épluchez et coupez les bananes en morceaux.","Mixez-les avec le lait, la glace vanille et le miel jusqu'à obtenir une texture bien lisse.","Versez dans des verres et dégustez immédiatement, bien frais."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Mousse au chocolat classique", cat:"dessert", tags:["classique"], kcal:320, p:6, c:22, f:22, prep:15, ing:["chocolat noir","œufs","sucre","beurre"], qty:["200 g","4","30 g","20 g"], steps:["Faites fondre le chocolat avec le beurre au bain-marie.","Séparez les blancs des jaunes, incorporez les jaunes au chocolat fondu hors du feu.","Montez les blancs en neige ferme avec le sucre, puis incorporez-les délicatement au mélange au chocolat.","Répartissez dans des ramequins et réservez au moins 3 h au réfrigérateur avant de déguster."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Crème brûlée", cat:"dessert", tags:["classique"], kcal:380, p:6, c:26, f:28, prep:40, ing:["crème liquide entière","jaunes d'œufs","sucre","vanille","cassonade"], qty:["500 ml","5","80 g","1 gousse","pour la caramélisation"], steps:["Préchauffez le four à 150°C. Faites chauffer la crème avec la gousse de vanille fendue et grattée, sans bouillir.","Fouettez les jaunes avec le sucre, versez la crème chaude dessus en fouettant, puis répartissez dans des ramequins.","Faites cuire au bain-marie 35 à 40 min jusqu'à ce que la crème soit prise mais encore légèrement tremblotante.","Laissez refroidir puis réservez au frais ; juste avant de servir, saupoudrez de cassonade et caramélisez au chalumeau ou sous le gril."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Tarte aux pommes maison", cat:"dessert", tags:["classique"], kcal:340, p:4, c:48, f:14, prep:55, ing:["pâte brisée","pommes","sucre","beurre","cannelle"], qty:["1 rouleau","6","60 g","20 g","1 pincée"], steps:["Préchauffez le four à 180°C. Foncez un moule avec la pâte brisée et piquez le fond à la fourchette.","Épluchez et coupez les pommes en fines lamelles, disposez-les en rosace sur la pâte.","Saupoudrez de sucre et de cannelle, parsemez de petits morceaux de beurre.","Enfournez 35 à 40 min jusqu'à ce que les pommes soient tendres et la pâte bien dorée."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Riz au lait vanille", cat:"dessert", tags:["classique"], kcal:300, p:8, c:50, f:7, prep:40, ing:["riz rond","lait","sucre","vanille"], qty:["150 g","1 L","80 g","1 gousse"], steps:["Versez le riz dans le lait avec la gousse de vanille fendue, portez doucement à ébullition.","Baissez le feu et laissez cuire à feu très doux 30 à 35 min en remuant de temps en temps, jusqu'à ce que le riz soit fondant.","Ajoutez le sucre en fin de cuisson, mélangez bien.","Répartissez dans des ramequins et servez tiède ou bien frais."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Flan pâtissier maison", cat:"dessert", tags:["classique"], kcal:320, p:8, c:46, f:11, prep:55, ing:["pâte brisée","lait","œufs","sucre","maïzena","vanille"], qty:["1 rouleau","600 ml","3","120 g","60 g","1 gousse"], steps:["Préchauffez le four à 180°C. Foncez un moule avec la pâte brisée.","Faites chauffer le lait avec la vanille. Fouettez les œufs, le sucre et la maïzena, puis versez le lait chaud dessus en fouettant.","Reversez le tout dans la casserole et faites épaissir à feu doux sans cesser de remuer, puis versez sur la pâte.","Enfournez 35 à 40 min jusqu'à ce que le dessus soit bien doré, laissez refroidir complètement avant de démouler."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Île flottante", cat:"dessert", tags:["classique"], kcal:280, p:8, c:40, f:9, prep:30, ing:["œufs","lait","sucre","vanille"], qty:["4","500 ml","100 g","1 gousse"], steps:["Séparez les blancs des jaunes. Montez les blancs en neige ferme avec 30 g de sucre.","Pochez des quenelles de blancs en neige 2 à 3 min dans de l'eau frémissante, puis égouttez-les sur du papier absorbant.","Préparez une crème anglaise en fouettant les jaunes avec le reste du sucre, puis en incorporant le lait chaud vanillé sur feu doux jusqu'à ce que la crème nappe la cuillère.","Versez la crème anglaise dans des coupelles et déposez les îles flottantes dessus, réservez au frais avant de servir."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Profiteroles au chocolat", cat:"dessert", tags:["classique"], kcal:420, p:8, c:40, f:24, prep:60, ing:["pâte à choux","glace vanille","chocolat noir","crème liquide"], qty:["16 choux (tout prêts ou maison)","500 ml","150 g","100 ml"], steps:["Faites fondre le chocolat avec la crème liquide au bain-marie pour obtenir une sauce lisse.","Fendez légèrement chaque chou et garnissez-le d'une boule de glace vanille.","Dressez 4 choux garnis par assiette et nappez généreusement de sauce chocolat chaude avant de servir aussitôt."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Fondant au chocolat cœur coulant", cat:"dessert", tags:["classique"], kcal:420, p:6, c:38, f:26, prep:25, ing:["chocolat noir","beurre","œufs","sucre","farine"], qty:["200 g","150 g","4","100 g","50 g"], steps:["Préchauffez le four à 210°C. Faites fondre le chocolat et le beurre ensemble au bain-marie.","Fouettez les œufs avec le sucre jusqu'à ce que le mélange blanchisse, incorporez le chocolat fondu puis la farine.","Répartissez dans des ramequins beurrés et enfournez 9 à 11 min : le centre doit rester coulant.","Démoulez délicatement et servez immédiatement, tant que le cœur est encore fondant."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Salade de fruits frais", cat:"dessert", tags:["classique"], kcal:140, p:2, c:32, f:1, prep:15, ing:["pomme","orange","kiwi","raisin","citron","menthe"], qty:["2","2","2","150 g","1/2","quelques feuilles"], steps:["Épluchez et coupez tous les fruits en morceaux réguliers.","Mélangez-les dans un saladier avec le jus de citron pour éviter qu'ils ne brunissent.","Ajoutez quelques feuilles de menthe ciselées et réservez au frais avant de servir."], diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Clafoutis aux cerises traditionnel", cat:"dessert", tags:["classique"], kcal:300, p:8, c:40, f:11, prep:45, ing:["cerises","œufs","lait","sucre","farine","beurre"], qty:["500 g","3","300 ml","80 g","70 g","10 g (pour le moule)"], steps:["Préchauffez le four à 180°C. Beurrez un plat à gratin et disposez les cerises dénoyautées au fond.","Fouettez les œufs avec le sucre, ajoutez la farine puis le lait progressivement pour obtenir une pâte lisse.","Versez la pâte sur les cerises et enfournez 35 à 40 min jusqu'à ce que le clafoutis soit doré et bien pris.","Laissez tiédir avant de déguster, saupoudré de sucre glace si désiré."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},

  {n:"Aubergines au four", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:160, p:3, c:14, f:11, prep:45, ing:["huile d'olive","aubergine"], qty:["2 c. à soupe","2"], steps:["Coupez chaque aubergine en deux dans le sens de la longueur sans les éplucher, puis zébrez la chair au couteau.","Badigeonnez la chair de chaque moitié d'huile d'olive.","Salez, poivrez et parsemez d'herbes de Provence.","Enfournez à 200°C (thermostat 6-7) jusqu'à ce que la chair soit bien tendre, et dégustez à la petite cuillère, à même la peau."], diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Amour de saumon en papillote", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:360, p:31, c:8, f:24, prep:40, ing:["saumon","tomate cerise","champignon de Paris","aneth","ail","citron","huile d'olive"], qty:["2 pavés","10","10","2 brins","1/2 gousse","1/2","1 filet"], steps:["Préchauffez le four à 180°C (thermostat 6). Lavez, essorez et ciselez l'aneth, puis pelez et émincez finement l'ail.","Nettoyez et émincez les champignons de Paris, puis coupez les tomates cerise en deux.","Déposez un pavé de saumon au centre de chaque feuille de papier cuisson, entourez-le des tomates et des champignons, puis parsemez d'aneth et d'ail.","Arrosez d'un filet de jus de citron et d'huile d'olive, salez et poivrez.","Fermez les papillotes et enfournez pendant 25 à 30 minutes. Dégustez chaud."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Pavé de saumon, poireaux & crème au curry", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:470, p:33, c:8, f:33, prep:45, ing:["saumon","poireau","crème fraîche épaisse","curry","huile"], qty:["2 pavés","2","10 cl","1 c. à café","1 c. à soupe"], steps:["Lavez les poireaux et coupez-les en rondelles (le blanc et environ 3 cm de vert).","Faites-les fondre à la poêle avec l'huile, à couvert, pendant environ 15 minutes, sans les laisser griller.","En fin de cuisson, salez, poivrez et ajoutez le curry selon votre goût.","Répartissez les poireaux dans un plat allant au four, recouvrez-les des pavés de saumon, poivrez si besoin, puis nappez le tout de crème fraîche.","Fermez hermétiquement le plat avec du papier aluminium et enfournez à 180-190°C (thermostat 6-7) pendant environ 20 minutes selon la taille des pavés."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Papillote de poulet, tomate & olives", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:260, p:30, c:6, f:12, prep:35, ing:["poulet","tomate","moutarde","olive","oignon","huile d'olive"], qty:["2 escalopes","1","2 c. à café","1 c. à soupe","1/2","1 filet"], steps:["Coupez la moitié de la tomate en tranches et disposez-les au centre d'une feuille de papier aluminium.","Badigeonnez les escalopes de poulet de moutarde, posez-les sur les tomates, puis recouvrez-les avec le reste de tomate tranchée.","Émincez l'oignon et coupez les olives en petits morceaux, répartissez-les sur les escalopes.","Arrosez d'un filet d'huile d'olive, salez, poivrez et parsemez d'herbes de Provence et de persil.","Fermez la papillote et faites cuire à four chaud (180°C) pendant 20 à 25 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Cabillaud et légumes au four", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:250, p:28, c:18, f:8, prep:75, ing:["cabillaud","carotte","courgette","brocoli","bouillon de légumes"], qty:["4 filets","100 g (5 carottes)","1 (100 g)","100 g","15 cl"], steps:["Coupez les carottes, la courgette et les brocolis en petits morceaux.","Dans un plat à gratin, disposez une couche de légumes crus, une couche de filets de poisson, puis recouvrez d'une nouvelle couche de légumes.","Arrosez de bouillon de légumes, salez, poivrez.","Couvrez de papier aluminium et faites cuire au four à 180°C pendant environ 1 heure. Servez avec du riz."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Sandwich au thon", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:390, p:32, c:40, f:10, prep:15, ing:["pain complet","thon au naturel","fromage blanc 0%","tomate séchée","citron","basilic"], qty:["2","2 boîtes","200 g","4","1/2","quelques feuilles"], steps:["Préparez la sauce : mélangez le fromage blanc avec le sel, le poivre, le basilic et quelques gouttes de jus de citron.","Émiettez le thon égoutté et incorporez-le à la sauce ; salez, poivrez et ajoutez à nouveau un peu de basilic.","Coupez les tomates séchées en morceaux et ajoutez-les à la préparation.","Ouvrez les pains complets sans séparer les deux parties, puis garnissez-les généreusement de la préparation au thon."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Pizza aux fruits de mer", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:460, p:28, c:52, f:16, prep:35, ing:["pâte à pizza","fruits de mer surgelés","ail","vin blanc sec","huile d'olive","citron","parmesan"], qty:["2","500 g","2 gousses","10 cl","2 c. à café","1/2","facultatif"], steps:["Étalez les pâtes à pizza. Dans une casserole, faites revenir l'ail dans l'huile d'olive, puis ajoutez le vin blanc, le jus de citron et les feuilles de laurier ; portez à ébullition.","Ajoutez les fruits de mer décongelés, mélangez, baissez le feu et laissez mijoter jusqu'à réduction de la sauce. Salez et poivrez à votre goût.","Retirez le laurier, puis étalez les fruits de mer sur les pâtes à l'aide d'un écumoir. Saupoudrez de parmesan si désiré.","Passez les pizzas sous le grill (ou une dizaine de minutes en position cuisson tarte) et servez aussitôt."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Papillotes de maquereau, tomate & citron", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:360, p:28, c:8, f:24, prep:45, ing:["maquereau","tomate","citron","moutarde de Dijon"], qty:["2","2","1","3 c. à soupe"], steps:["Brossez le citron et coupez-le en rondelles, ainsi que les tomates lavées.","Sur de grands carrés de papier aluminium ou de papier sulfurisé, disposez des rondelles de citron et de tomates, puis parsemez d'herbes de Provence.","Badigeonnez les maquereaux de moutarde forte sur les deux faces et posez-les sur les rondelles de citron et de tomates.","Recouvrez-les à nouveau d'herbes de Provence, puis de rondelles de tomates et de citron.","Fermez les papillotes, posez-les dans un plat creux allant au four et faites cuire à four chaud (210°C, thermostat 7) pendant environ 30 minutes selon la taille des poissons, en baissant le four en fin de cuisson."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Gratin de légumes, riz & jambon", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:520, p:25, c:65, f:18, prep:50, ing:["riz","poireau","sauce tomate","courgette","béchamel","jambon fumé","gruyère","chapelure"], qty:["150 g (poids cru)","1","100 g","300 g","25 cl","2 tranches","60 g","1 c. à soupe"], steps:["Décongelez les courgettes puis faites-les dorer à la poêle à feu vif ; réservez-les.","Émincez finement le poireau et faites-le suer dans la même poêle pendant 6 à 7 minutes.","Pendant ce temps, faites cuire le riz et préparez la béchamel.","Dans un plat à gratin, disposez en couches le poireau, les courgettes, la moitié du riz, les aromates (persil, thym, romarin), du sel, du poivre, la sauce tomate, le jambon fumé et le reste du riz.","Couvrez de béchamel, parsemez de gruyère râpé et d'un peu de chapelure.","Enfournez environ 25 à 30 minutes à 180°C."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Roulés de jambon, sauce moutarde", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:300, p:12, c:3, f:27, prep:20, ing:["jambon","moutarde","margarine","crème fraîche liquide"], qty:["4 tranches","1 c. à café","1 noix","15 cl"], steps:["Roulez les tranches de jambon.","Faites-les revenir dans une poêle avec la noix de margarine, 1 minute de chaque côté à feu vif, puis réservez-les.","Dans la même poêle, versez la crème fraîche, ajoutez la moutarde et mélangez à feu moyen jusqu'à ce que la moutarde soit bien diluée. Ajoutez les herbes de Provence, salez et poivrez selon votre goût.","Servez le jambon nappé de la sauce."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Endives au jambon et gruyère", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:240, p:16, c:8, f:16, prep:35, ing:["jambon blanc","endives","crème fraîche","gruyère râpé"], qty:["2 tranches","2","20 cl (8% MG)","40 g"], steps:["Faites cuire les endives à la vapeur jusqu'à ce qu'elles soient tendres.","Enroulez chaque endive dans une tranche de jambon blanc et disposez-les dans un plat allant au four.","Nappez de crème fraîche, saupoudrez d'une pointe de muscade, salez et poivrez, puis recouvrez de gruyère râpé.","Enfournez environ 15 minutes à 240°C, jusqu'à ce que le gruyère soit gratiné."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Risotto de brocolis aux amandes", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:380, p:13, c:48, f:15, prep:40, ing:["riz brun","oignon","huile d'olive","bouillon de volaille","brocolis","amandes grillées","parmesan"], qty:["90 g","1/2","1 c. à soupe","40 cl","250 g","1 c. à soupe","25 g"], steps:["Faites revenir l'oignon émincé dans l'huile d'olive pendant 3 minutes, puis ajoutez le riz brun et remuez jusqu'à ce qu'il soit bien enrobé d'huile.","Versez le bouillon de volaille petit à petit et portez à ébullition. Salez, poivrez, ajoutez les amandes, couvrez et laissez mijoter 20 minutes.","Ajoutez les brocolis et poursuivez la cuisson 8 minutes, jusqu'à ce que le bouillon soit absorbé.","Incorporez le parmesan, dressez dans un plat de service, saupoudrez d'amandes grillées et servez bien chaud."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:false}},
  {n:"Flan de chou-fleur au jambon", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:330, p:29, c:23, f:14, prep:40, ing:["chou-fleur","jambon","oeuf","lait écrémé","maïzena","gruyère râpé"], qty:["1/2","100 g","2","25 cl","1 c. à soupe et demie","30 g"], steps:["Faites blanchir le chou-fleur quelques minutes à l'eau bouillante.","Battez les œufs en omelette avec le lait, le gruyère râpé et la maïzena, puis salez, poivrez et ajoutez une pointe de muscade. Incorporez le jambon coupé en dés.","Huilez légèrement un plat à gratin et disposez-y le chou-fleur.","Recouvrez avec la préparation aux œufs et enfournez 20 à 30 minutes à 210°C (thermostat 7)."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Pizza minceur au blanc de dinde", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:290, p:18, c:46, f:3, prep:45, ing:["farine","yaourt nature 0%","jaune d'oeuf","concentré de tomates","poivron","blanc de dinde","carré frais 0%"], qty:["100 g","125 g (1 pot nature 0%)","1","2 c. à soupe","1/2","2 tranches","2"], steps:["Préparez la pâte en mélangeant la farine, le yaourt nature 0% et le jaune d'œuf avec une pincée de sel, jusqu'à obtenir une boule. Étalez-la en l'étirant bien (elle est un peu élastique), en rajoutant un peu de farine si besoin.","Déposez le disque de pâte, sans matière grasse, sur une plaque antiadhésive.","Délayez le concentré de tomates avec un peu d'eau sur feu doux, sans trop diluer, puis étalez-le sur la pâte. Répartissez ensuite le blanc de dinde et le poivron coupés en petits morceaux.","Émiettez le carré frais sur le dessus.","Enfournez 30 minutes à 185°C."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Darnes de saumon à la moutarde et citron", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:310, p:31, c:1, f:20, prep:30, ing:["saumon","moutarde","citron"], qty:["2 (300 g)","1 c. à soupe","1 c. à soupe (jus)"], steps:["Préchauffez le four à 200°C (thermostat 6).","Disposez les darnes de saumon dans un plat antiadhésif allant au four.","Mélangez la moutarde et le jus de citron dans un bol, puis arrosez-en les darnes.","Salez et poivrez légèrement (sauf si vous utilisez une moutarde forte), puis parsemez de persil haché.","Enfournez 20 minutes à four chaud."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Filet mignon de porc en papillote aux légumes", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:310, p:44, c:13, f:10, prep:60, ing:["filet mignon","oignon","carotte","tomate","poivron","ail","huile d'olive"], qty:["1 (350 g)","1","1","1","1/4","1/2 gousse","1/2 c. à soupe"], steps:["Découpez deux grandes feuilles de papier sulfurisé ou d'aluminium, assez longues pour bien refermer les papillotes, et placez la moitié du filet mignon au centre de chacune.","Épluchez et coupez en morceaux l'oignon, la carotte, le poivron et la tomate.","Répartissez les légumes sur chaque filet mignon en les alternant, ajoutez l'ail, le laurier et le thym, puis arrosez d'un filet d'huile d'olive, salez et poivrez.","Fermez les papillotes et disposez-les dans un plat.","Enfournez au moins 45 minutes, en vérifiant la cuisson de la viande avec la pointe d'un couteau (si elle est encore rosée, prolongez de 10 minutes).","Servez dans le plat de cuisson en retirant le papier, en conservant bien le jus avec la viande et les légumes."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Filets de poisson à la moutarde et cornichons", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:210, p:37, c:2, f:5, prep:30, ing:["poisson (filet)","moutarde de Dijon","crème fraîche allégée","cornichon"], qty:["4 (300 g)","1 c. à soupe et demie","1 c. à soupe et demie","1 c. à soupe (hachés)"], steps:["Disposez les filets de poisson dans un plat légèrement beurré, salez et poivrez légèrement.","Enfournez 10 minutes dans un four préchauffé à 210°C (thermostat 7).","Videz l'eau de cuisson rendue par le poisson.","Nappez du mélange crème fraîche, moutarde et cornichons hachés, puis remettez à cuire 10 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Filets de poulet à la crème de poivron", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:410, p:45, c:5, f:20, prep:35, ing:["poulet (filet)","poivron rouge","beurre","crème liquide","crème fraîche épaisse"], qty:["3 (350 g)","1/2","10 g","10 cl","2 c. à soupe"], steps:["Découpez les filets de poulet en petites lamelles (environ 3 cm x 1 cm) et faites-les revenir dans une sauteuse avec le beurre fondu. Pendant ce temps, coupez le poivron en tous petits dés en retirant bien les parties blanches.","Ajoutez le poivron au poulet et laissez cuire jusqu'à ce que le poulet soit bien rosé. Versez la crème liquide, salez, poivrez, mélangez bien et laissez cuire très doucement environ 20 minutes.","Juste avant de servir, ajoutez la crème fraîche épaisse pour lier la sauce.","Servez avec du riz sauvage."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Gratin de courgettes et champignons", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:290, p:15, c:27, f:14, prep:45, ing:["courgette","champignons de Paris","oignon","ail","huile d'olive","vinaigre balsamique","béchamel allégée","fromage râpé"], qty:["500 g","100 g","1/2","1 gousse","1/2 c. à café","1/2 c. à soupe","25 cl","30 g"], steps:["Dans une sauteuse, faites chauffer l'huile puis faites revenir l'oignon et l'ail. Ajoutez le vinaigre balsamique.","Une fois les oignons revenus, ajoutez les courgettes et les champignons, couvrez et laissez cuire à feu moyen 15 minutes.","Pendant ce temps, préparez la béchamel allégée.","Découvrez les légumes, salez, poivrez, ajoutez une pincée de cumin, puis faites cuire à feu fort 10 minutes en remuant régulièrement, jusqu'à ce que les légumes aient rendu leur eau.","Versez les légumes dans un plat à gratin, recouvrez de béchamel puis de fromage râpé, et passez sous le gril jusqu'à ce que le fromage soit doré."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Pois chiches au thon à la méridionale", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:440, p:33, c:52, f:12, prep:35, ing:["pois chiches","tomate pelée","thon au naturel","courgette","oignon","ail","huile d'olive","basilic"], qty:["1 boîte (240 g égouttés)","1 boîte (400 g)","1 boîte (140 g égoutté)","250 g","1","1 gousse","1 c. à soupe","quelques feuilles"], steps:["Faites revenir l'oignon émincé et l'ail dans un peu d'huile d'olive.","Ajoutez les pois chiches égouttés, les tomates pelées avec leur jus, ainsi que le thon et son jus. Mélangez bien, salez, poivrez, ajoutez du piment selon votre goût et le basilic émincé.","Lavez les courgettes non épluchées, émincez-les en fines tranches et ajoutez-les au mélange.","Faites cuire à découvert, en remuant de temps à autre, environ 20 minutes, jusqu'à ce que les courgettes soient bien fondantes et que l'eau de cuisson soit presque entièrement évaporée.","Rectifiez l'assaisonnement si besoin et servez bien chaud."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Saumon à la sauce tomate-basilic et tagliatelles", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:530, p:39, c:46, f:21, prep:30, ing:["saumon","tomate pelée","basilic","tagliatelles fraîches"], qty:["300 g (2 pavés)","120 g (en boîte)","1/2 bouquet","175 g"], steps:["Mixez les tomates pelées et mélangez-les au basilic haché finement, salez et poivrez, puis réservez au frais.","Formez un lit de gros sel d'environ 0,5 cm dans une poêle et faites chauffer.","Posez les pavés de saumon peau contre le sel, couvrez d'un couvercle ou de papier aluminium et laissez cuire.","Pendant ce temps, faites cuire les tagliatelles selon les indications du paquet.","Quand le saumon est cuit, décollez la chair de la peau (qui reste dans la poêle) et servez avec la sauce fraîche tomate-basilic et les tagliatelles."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Thon grillé mariné à l'ail et aux oignons", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:330, p:44, c:5, f:15, prep:30, ing:["thon","oignon","thym","clou de girofle","ail","poivre de Cayenne","huile d'olive"], qty:["300 g (2 pavés)","1","1 branche","4","1 gousse","1 pincée","2 c. à soupe"], steps:["La veille, piquez les parties rouge foncé du thon avec les clous de girofle et piquez la chair rose de quelques éclats d'ail.","Épluchez et émincez l'oignon en fines rondelles, effeuillez le thym.","Huilez les pavés de thon sur les deux faces, salez, poivrez et saupoudrez légèrement de poivre de Cayenne.","Posez-les sur un lit d'oignons et de thym, couvrez et laissez mariner 24 heures au réfrigérateur en retournant les pavés au moins une fois.","Le jour même, faites cuire au barbecue ou au grill 10 à 15 minutes en surveillant la cuisson pour que la chair reste moelleuse sans être trop sèche."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Gratin de potiron au fromage et à la muscade", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:200, p:10, c:18, f:9, prep:35, ing:["potiron","oeuf","lait écrémé en poudre","fromage râpé","muscade"], qty:["500 g","1","2 c. à soupe","30 g","1/2 pincée"], steps:["Pelez le potiron, coupez-le en gros dés et faites-le cuire à la vapeur (environ 15 minutes en cocotte sous pression). Écrasez-le à la fourchette dans une jatte.","Battez sommairement l'œuf avec le lait écrémé en poudre, incorporez à la purée de potiron, puis salez, poivrez et ajoutez la muscade.","Saupoudrez de fromage râpé et faites gratiner sous le gril du four jusqu'à coloration souhaitée."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Émincé de saumon au cidre et au safran", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:540, p:37, c:50, f:20, prep:40, ing:["saumon","cidre brut","échalote","crème allégée","basilic","farfalle","safran","concombre","pêche jaune"], qty:["300 g (2 pavés, en cubes)","25 cl","1","5 cl","1/2 poignée (ciselé)","125 g","1/2 dosette (+ quelques filaments)","6 rondelles","1/2"], steps:["Préchauffez le four à 200°C.","Dans un plat allant au four, disposez les cubes de saumon salés et poivrés, répartissez l'échalote dessus puis couvrez à hauteur avec le cidre.","Faites cuire 10 à 15 minutes au four (le poisson ne doit pas être trop cuit).","Pendant ce temps, faites cuire les farfalle environ 10 minutes. Récupérez le jus de cuisson du saumon, filtrez-le et faites-le réduire de moitié dans une casserole.","Quand le jus est réduit, ajoutez la crème et le safran, remuez, puis ajoutez le basilic ciselé. Coupez le feu et remettez délicatement le saumon dans la sauce pour le réchauffer.","Dans les assiettes, alternez les rondelles de concombre et de pêche, disposez les farfalle au centre, ajoutez les cubes de saumon, nappez de sauce et décorez de quelques filaments de safran."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Brick de thon", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:270, p:33, c:15, f:9, prep:30, ing:["thon au naturel","feuille de brick","yaourt nature","échalote","huile d'olive","endive"], qty:["250 g (1 boîte)","2","1","2","1 filet","1 (à volonté)"], steps:["Émiettez le thon bien égoutté dans un saladier.","Coupez les échalotes très finement et mélangez-les au thon. Salez, poivrez, ajoutez du persil et du basilic ciselés ainsi qu'un filet d'huile d'olive, puis terminez par le yaourt et mélangez bien.","Préchauffez le four à 180°C.","Répartissez la préparation au centre des feuilles de brick et repliez-les comme un paquet, rebords en dessous.","Enfournez 15 minutes, jusqu'à ce que les bricks commencent à colorer.","Servez avec une salade d'endives."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Poulet au fromage de chèvre et poivron rouge", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:360, p:39, c:4, f:19, prep:45, ing:["poulet","fromage de chèvre","poivron rouge","ail","cumin","cannelle","huile d'olive"], qty:["2 blancs (environ 300 g)","1 crottin de Chavignol","1","1/2 tête","1 pincée","1 pincée","1 filet"], steps:["Coupez les blancs de poulet dans le sens de la longueur pour obtenir 4 fines escalopes, puis saupoudrez-les de cannelle, de cumin, de poivre et d'un peu d'estragon.","Déposez du papier aluminium sur la grille du four et disposez-y 2 des escalopes de poulet.","Coupez le fromage de chèvre en grosses lamelles, répartissez-les sur les escalopes puis recouvrez avec les 2 escalopes restantes pour former des paquets.","Coupez le poivron en deux et recouvrez chaque paquet de poulet d'une moitié.","Coupez la tête d'ail en 4 et disposez les quartiers sur la grille entre les paquets de poulet, ajoutez un filet d'huile d'olive et une pincée de sel.","Enfournez à 220°C pendant 25 à 30 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Courgettes carbonara au jambon", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:180, p:21, c:8, f:6, prep:25, ing:["jambon","crème fraîche","courgette"], qty:["200 g","4 c. à soupe","400 g"], steps:["Faites cuire les courgettes à l'eau ou à la vapeur.","Pendant ce temps, faites revenir le jambon coupé en dés dans une poêle sans matière grasse, ajoutez la crème fraîche, salez et poivrez, puis laissez mijoter 2 minutes en remuant.","Ajoutez les courgettes égouttées et mélangez bien.","Laissez cuire à couvert jusqu'à ce que la crème fraîche soit absorbée par les courgettes."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Tarte au thon et au fromage blanc", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:520, p:32, c:38, f:28, prep:45, ing:["pâte feuilletée","thon","fromage blanc battu","oignon","persil","farine"], qty:["1 (rouleau)","250 g (1 boîte)","200 g","1","1 petit bouquet","1 c. à café"], steps:["Préchauffez le four à 220°C (thermostat 7).","Étalez la pâte feuilletée dans un moule et piquez-la à la fourchette.","Émiettez le thon égoutté dans un bol et ajoutez le fromage blanc battu.","Hachez l'oignon et le persil, ajoutez-les à la préparation, assaisonnez à votre goût (sel, poivre) et incorporez la farine.","Mélangez le tout et répartissez sur la pâte.","Enfournez environ 30 minutes et servez chaud."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Brick au chèvre, jambon et tomate", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:270, p:13, c:28, f:11, prep:25, ing:["jambon blanc","tomate","feuille de brick","fromage de chèvre"], qty:["2 tranches","2","4","1/2 bûche"], steps:["Coupez les tomates en rondelles et parsemez-les généreusement de persil haché, de sel et de poivre.","Hachez grossièrement le jambon.","Sur chaque feuille de brick, disposez deux tranches de bûche de chèvre, le jambon puis les tomates persillées.","Repliez les feuilles de brick en ramenant les rebords en dessous.","Faites cuire au four chaud environ 10 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Cake aux tomates séchées et au parmesan", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:400, p:11, c:33, f:26, prep:60, ing:["farine","maïzena","levure chimique","huile","lait","tomate séchée","oeuf","parmesan"], qty:["35 g","35 g","1/3 sachet","4 cl","4 cl","4","1","25 g"], steps:["Préchauffez le four à 180°C (thermostat 6).","Mélangez la farine, la maïzena et la levure chimique dans un récipient.","Dans un autre récipient, battez légèrement l'œuf à la fourchette, ajoutez le lait et l'huile, salez et poivrez.","Versez cette préparation sur le mélange à base de farine et mélangez délicatement.","Incorporez le parmesan puis les tomates séchées coupées en petits morceaux, mélangez délicatement.","Versez dans un moule à cake beurré et enfournez pendant 45 minutes. Laissez refroidir avant de démouler."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Roulés de poireaux au saumon fumé", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:200, p:13, c:8, f:12, prep:35, ing:["poireau","saumon fumé","crème fraîche épaisse allégée","muscade","citron"], qty:["4","4 tranches","20 cl","1 pincée","1"], steps:["Faites cuire les blancs de poireau à la vapeur ou à l'eau pendant 20 minutes (inutile si vous utilisez des blancs de poireaux en conserve).","Enroulez chaque blanc de poireau dans une tranche de saumon fumé et disposez les roulés dans un plat allant au four.","Mélangez la crème fraîche avec le jus de citron et la muscade, salez et poivrez.","Versez cette préparation sur les roulés.","Enfournez à 170°C (thermostat 5-6) pendant une dizaine de minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Osso bucco de veau à la gremolata", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:490, p:45, c:42, f:14, prep:150, ing:["jarret de veau","huile","tomate","farine","ail","citron","anchois","persil","riz"], qty:["2 tranches","1 c. à soupe","200 g","2 c. à soupe","1 gousse","1/2 (zeste)","1 filet","1 c. à soupe","120 g (poids cru)"], steps:["Farinez chaque tranche de jarret de veau.","Faites chauffer l'huile dans une grande casserole et faites-y revenir le veau.","Ajoutez les tomates et leur jus ainsi qu'un verre d'eau, salez, poivrez, couvrez et laissez mijoter 2 h à 2 h 30 à feu doux, jusqu'à ce que la viande se détache des os.","Pelez et hachez la gousse d'ail, mélangez-la avec le zeste de citron, le persil haché et l'anchois haché pour obtenir une gremolata.","Versez ce mélange sur la viande et servez avec le riz cuit."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Brochettes de poulet et tomates cerises", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:230, p:39, c:9, f:5, prep:30, ing:["poulet","tomate cerise","farine","citron"], qty:["250 g","250 g","1/2 c. à soupe","1/2"], steps:["Coupez les blancs de poulet en petits morceaux et faites-les mariner dans le jus de citron.","Égouttez le poulet, farinez-le légèrement, puis enfilez sur des pics à brochette en alternant avec les tomates cerises.","Faites cuire les brochettes dans une poêle sans matière grasse en les tournant régulièrement, jusqu'à ce que le poulet soit bien doré. Salez et poivrez en fin de cuisson."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Spaghetti à la julienne de légumes et brocolis", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:550, p:20, c:83, f:13, prep:30, ing:["spaghetti complet","julienne de légumes","brocolis","crème liquide légère","bouillon de légumes","huile d'olive","pignons de pin"], qty:["225 g","300 g","50 g","10 cl","1/2 c. à soupe","1/2 c. à soupe","1 c. à soupe"], steps:["Faites bouillir de l'eau avec le bouillon de légumes.","Décongelez la julienne de légumes au micro-ondes et égouttez-la bien.","Faites cuire les brocolis à la vapeur.","Faites revenir la julienne à feu doux dans l'huile d'olive, ajoutez les brocolis, salez et poivrez.","Faites griller les pignons à sec dans une poêle, puis réservez-les sur du papier absorbant.","Faites cuire les pâtes al dente dans l'eau bouillonnante, égouttez-les et versez-les dans une sauteuse avec les légumes, mélangez.","Ajoutez progressivement la moitié de la crème et mélangez à nouveau.","Dressez dans le plat de service, ajoutez les pignons et le reste de crème, mélangez une dernière fois. Saupoudrez de parmesan ou de chapelure selon les goûts."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:false}},
  {n:"Nuggets de poulet épicés", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:480, p:68, c:31, f:14, prep:25, ing:["poulet","farine","lait","gingembre","piment en poudre","curry","cumin","muscade"], qty:["450 g","75 g","20 cl","1 c. à café","2 c. à café","1 c. à café","1 c. à café","1 c. à café"], steps:["Coupez les blancs de poulet en gros dés.","Mélangez les épices (gingembre, piment, curry, cumin, muscade) avec la farine dans un saladier.","Trempez les morceaux de poulet dans le lait, puis roulez-les dans le mélange épices-farine.","Disposez les morceaux dans une poêle chaude et légèrement huilée, salez, et faites cuire 5 minutes de chaque côté."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Escalopes de dinde aux courgettes et au citron", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:260, p:32, c:5, f:12, prep:20, ing:["dinde","courgette","huile d'olive","citron","olive noire","sauge"], qty:["2 escalopes","2","1 c. à soupe","1/2","50 g","1 c. à café"], steps:["Faites chauffer l'huile d'olive dans une poêle et faites-y revenir les escalopes de dinde coupées en morceaux.","Ajoutez les courgettes et le citron coupés en fines rondelles, salez, poivrez et ajoutez la sauge.","Quelques minutes avant la fin de la cuisson, ajoutez les olives noires."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Salade de raie aux haricots verts", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:210, p:35, c:14, f:2, prep:35, ing:["raie","haricots verts","aneth","court-bouillon","citron"], qty:["300 g (2 ailes)","400 g","1 c. à soupe","1/2 cube","1"], steps:["Faites cuire les haricots verts dans de l'eau salée, puis égouttez-les et rincez-les à l'eau froide.","Faites pocher les ailes de raie dans de l'eau additionnée du cube de court-bouillon, puis égouttez.","Détachez la chair du poisson et mélangez-la aux haricots verts, salez, poivrez, ajoutez l'aneth et le jus de citron.","Servez tiède ou frais."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Osso buco de veau au céleri-rave et carottes", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:370, p:45, c:17, f:14, prep:80, ing:["jarret de veau","oignon","carotte","tomate","céleri-rave","navet","ail","basilic","vin blanc","persil"], qty:["2 tranches","1","1","3","1/4","50 g","2 gousses","1 bouquet","1/2 verre (10 cl)","1 c. à soupe"], steps:["Faites griller les tranches de jarret de veau (osso-buco) pendant 10 minutes.","Dès que la viande est dorée, ajoutez les carottes coupées en rondelles, l'oignon émincé, l'ail pilé, les tomates coupées en rondelles, les navets épluchés et coupés en quartiers, et le céleri-rave coupé en bâtonnets de 5 cm.","Mouillez avec le vin blanc, salez et poivrez, couvrez et laissez mijoter 50 minutes à 1 heure.","À mi-cuisson, ajoutez la moitié du basilic.","En cours de cuisson, ajoutez éventuellement un verre d'eau si besoin.","Juste avant de servir, ajoutez le reste du basilic et le persil haché."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Penne aux courgettes et tomates", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:370, p:14, c:47, f:13, prep:25, ing:["penne","courgette","tomate pelée","huile","thym","laurier","origan","parmesan"], qty:["100 g","2","2 boîtes (400 g)","4 c. à café","1 pincée","2 feuilles","1 pincée","2 c. à soupe"], steps:["Mettez les pâtes à cuire selon les instructions du paquet.","Lavez et coupez les courgettes en dés. Faites-les suer dans l'huile un instant, puis ajoutez une pincée d'origan, de thym et la feuille de laurier.","Versez les tomates pelées coupées en morceaux et laissez cuire jusqu'à ce que les courgettes soient tendres. Salez et poivrez selon votre goût.","Égouttez les pâtes et dressez-les dans les assiettes. Versez la sauce aux courgettes et tomates dessus, puis saupoudrez de parmesan."], diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Rôti de porc aux herbes de Provence", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:360, p:51, c:0, f:17, prep:70, ing:["rôti de porc"], qty:["500 g"], steps:["Saupoudrez le dessus du rôti de porc d'herbes de Provence.","Enveloppez-le dans du papier aluminium et placez-le dans un plat allant au four préchauffé à 210°C, puis faites cuire environ 1 heure, en comptant 30 minutes de cuisson par 500 g.","Une fois cuit, laissez le rôti refroidir puis servez-le avec différentes sauces et une salade."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Gratin de salsifis et jambon", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:460, p:26, c:20, f:30, prep:35, ing:["jambon blanc","gruyère râpé","tomate","salsifis","crème fraîche allégée","lait écrémé","jaune d'oeuf"], qty:["2 tranches","100 g","1","500 g (surgelés)","15 cl","1/2 verre","1/2"], steps:["Précuisez les salsifis surgelés environ 10 minutes au micro-ondes.","Répartissez-les dans un plat à gratin et parsemez de jambon blanc coupé en morceaux.","Dans un récipient, mélangez la crème fraîche, le lait écrémé et le jaune d'oeuf, puis salez et poivrez.","Versez ce mélange sur les salsifis et le jambon.","Coupez la tomate en tranches fines et recouvrez-en le plat.","Parsemez de gruyère râpé et enfournez à th. 7/8 (220°C) pendant 20 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Poêlée de dinde, aubergine & tomate", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:210, p:24, c:17, f:6, prep:25, ing:["huile d'olive","aubergine","moutarde","tomate","curry","escalope de dinde","pâtes cuites"], qty:["1 filet","1/2","1 c. à soupe","2","3 pincées (facultatif)","1 (env. 150 g)","3 c. à soupe (facultatif)"], steps:["Faites chauffer un filet d'huile dans une poêle.","Ajoutez l'aubergine coupée en dés, les tomates pelées coupées en lamelles et un verre d'eau. Laissez cuire 9 à 10 minutes jusqu'à évaporation presque totale de l'eau.","Ajoutez l'escalope de dinde coupée en cubes et la moutarde, salez et poivrez. Laissez cuire environ 5 minutes en surveillant la cuisson : le cœur de la dinde doit être blanc.","Ajoutez le curry et les pâtes déjà cuites, puis laissez cuire encore 2 minutes à feu doux en mélangeant bien."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Poisson blanc aux poireaux et échalotes", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:390, p:30, c:20, f:20, prep:50, ing:["poisson blanc","poireau","échalote","crème allégée","huile d'olive","chapelure","curry"], qty:["2 filets (300 g)","4","2","20 cl","1 c. à soupe","2 c. à soupe","1 pincée"], steps:["Coupez finement les poireaux et les échalotes en petits tronçons.","Dans une sauteuse ou un wok, faites chauffer l'huile d'olive et faites-y étuver les poireaux et les échalotes jusqu'à ce qu'ils brunissent légèrement.","Versez la crème allégée de façon à couvrir autant que possible le poisson et les poireaux, assaisonnez d'une pincée de curry, salez et poivrez.","Dans un plat allant au four, versez un quart de cette préparation, déposez le poisson par-dessus et recouvrez avec le reste.","Saupoudrez de chapelure et faites cuire à four chaud (thermostat 7, 210°C) pendant 30 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Seiches à la tomate et aux champignons de Paris", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:210, p:30, c:12, f:3, prep:25, ing:["seiche","tomate","ail","champignons de Paris","sucre"], qty:["12 (env. 300 g)","4","2 gousses","115 g égouttés","2 pincées"], steps:["Portez de l'eau à ébullition et faites-y cuire les seiches environ 10 minutes, jusqu'à ce qu'elles deviennent blanches.","Pendant ce temps, pelez les tomates, retirez le trognon, et pelez l'ail.","Égouttez et rincez les seiches, puis ajoutez-les dans la poêle avec les tomates coupées en morceaux, l'ail en lamelles, les champignons et le sucre. Salez et poivrez selon votre goût, et laissez mijoter quelques minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Pain de colin et courgettes", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:420, p:40, c:27, f:15, prep:55, ing:["colin","courgette","semoule de blé dur","lait écrémé","oeuf","gruyère râpé","beurre","citron","aneth"], qty:["400 g (2 tranches)","200 g","50 g","200 ml","2","10 g","pour le moule","1 (jus)","à volonté"], steps:["Préchauffez le four à th. 7 (220°C).","Faites cuire les tranches de poisson arrosées de jus de citron, salées et poivrées, au micro-ondes environ 5 minutes à puissance moyenne.","Pendant ce temps, lavez et râpez les courgettes.","Battez les oeufs avec le lait, les courgettes râpées, le poisson émietté et la semoule de blé dur.","Ajoutez les herbes (aneth, basilic, persil...), salez et poivrez la préparation.","Versez la préparation dans un moule beurré et saupoudrez de gruyère râpé.","Faites cuire au four environ 40 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
  {n:"Noisettes d'agneau au curry et pamplemousse rose", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:480, p:30, c:21, f:30, prep:25, ing:["noisette d'agneau","oignon rouge","pamplemousse rose","huile d'olive","curry","coriandre fraîche"], qty:["300 g","250 g","1","1 c. à soupe","2 c. à café","1 bouquet"], steps:["Coupez l'agneau en dés, pelez les oignons rouges et coupez-les en rondelles, puis pelez le pamplemousse à vif en récupérant le jus.","Faites chauffer l'huile d'olive dans une poêle et faites-y dorer les dés d'agneau. Salez, poivrez.","Saupoudrez de curry, mélangez et prolongez la cuisson d'une minute.","Ajoutez les oignons et le jus de pamplemousse, puis laissez mijoter à feu doux pendant 5 minutes. Ajoutez les quartiers de pamplemousse et la coriandre hachée.","Servez aussitôt, parsemé de coriandre fraîche."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Dinde, mangue et paprika", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:220, p:36, c:10, f:4, prep:25, ing:["filet de dinde","mangue","poivron rouge","fromage blanc 0%","paprika","piment en poudre"], qty:["2","1/2","1/2","50 g","1 c. à soupe","1/2 c. à café"], steps:["Coupez les filets de dinde en petits morceaux de 3 cm et faites-les revenir à la poêle environ 10 minutes avec le paprika, à feu moyen. Salez, poivrez.","Pendant ce temps, coupez le poivron et la mangue en petits dés.","Dans une casserole, mélangez le fromage blanc, le poivron, la mangue, le reste de paprika et le piment. Salez, poivrez, goûtez et rectifiez l'assaisonnement en piment ou en paprika si nécessaire.","Faites chauffer sans laisser bouillir, puis servez la dinde nappée de cette sauce."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Papillotes de poulet, poireaux & moutarde", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:300, p:32, c:16, f:10, prep:35, ing:["blanc de poulet","poireau","carotte","moutarde de Dijon","beurre"], qty:["2","2","2","2 c. à soupe (au total)","1 noisette"], steps:["Coupez les blancs de poireaux et les carottes en petits bâtons fins.","Faites-les cuire à couvert avec une noisette de beurre, un peu d'eau et une cuillère à café de moutarde, jusqu'à ce qu'ils soient tendres.","Sur une feuille de papier sulfurisé, déposez une généreuse cuillère de légumes, posez un blanc de poulet par-dessus et recouvrez d'une cuillère à soupe de moutarde forte. Salez, poivrez.","Refermez les papillotes et faites-les cuire au four déjà chaud (thermostat 8, 250°C) pendant 15 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
  {n:"Papillotes de poulet, courgettes & semoule au cumin", cat:"déjeuner/dîner", tags:["perte_de_poids","equilibre"], kcal:490, p:32, c:45, f:17, prep:55, ing:["cuisse de poulet","courgette","poivron","semoule","huile d'olive","cumin"], qty:["2","2","1/2","1 verre","1 c. à café","1 c. à café"], steps:["Épluchez et coupez les courgettes en tranches, et le poivron en lanières.","Sur une feuille de papier aluminium, déposez un demi-verre de semoule, puis les courgettes et le poivron. Saupoudrez de cumin.","Déposez le poulet par-dessus et arrosez d'une cuillère à café d'huile d'olive. Salez, poivrez.","Refermez les papillotes et faites cuire au four (thermostat 7, 210°C) pendant 30 minutes, puis ouvrez-les et passez au grill encore 15 minutes."], diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Blanquette de veau, carottes & champignons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:650,p:50,c:18,f:42,prep:120,ing:["veau à blanquette","oignon","carotte","champignons de Paris","farine","bouillon de volaille","vin blanc","crème fraîche","jaune d'oeuf","citron"],qty:["500 g","1","1","200 g","2 c. à soupe","1 cube","15 cl","10 cl","1","jus de ½ citron"],steps:["Faites revenir la viande dans un peu de beurre jusqu'à ce que les morceaux soient dorés.","Saupoudrez de farine et mélangez bien.","Ajoutez 2 à 3 verres d'eau et le cube de bouillon, puis le vin blanc ; complétez avec de l'eau si nécessaire pour bien couvrir la viande.","Coupez la carotte en rondelles et émincez l'oignon, puis incorporez-les à la viande avec les champignons.","Salez, poivrez et laissez mijoter à feu très doux pendant 1h30 à 2h, en remuant de temps en temps et en ajoutant de l'eau si nécessaire.","Dans un bol, mélangez la crème fraîche, le jaune d'oeuf et le jus de citron. Ajoutez ce mélange hors du feu au dernier moment, remuez bien et servez aussitôt."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Lasagnes bolognaise, béchamel au parmesan",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:820,p:42,c:68,f:44,prep:90,ing:["boeuf haché","plaques de lasagnes","oignon","carotte","céleri branche","ail","purée de tomate","vin rouge","beurre","farine","lait","fromage râpé","parmesan"],qty:["150 g","150 g","1","1 petite","½ branche","1 gousse","200 g","5 cl","40 g","25 g","25 cl","30 g","30 g"],steps:["Faites revenir l'ail haché et l'oignon émincé dans un peu d'huile d'olive.","Ajoutez la carotte et le céleri hachés, puis la viande hachée, et faites revenir le tout.","Ajoutez le vin rouge et laissez cuire jusqu'à évaporation.","Ajoutez la purée de tomate, un peu d'eau, du thym et une demi-feuille de laurier. Salez, poivrez et laissez mijoter à feu doux pendant 45 minutes.","Préparez la béchamel : faites fondre le beurre, ajoutez la farine hors du feu et mélangez bien.","Remettez sur le feu et fouettez jusqu'à obtenir un mélange lisse, puis versez le lait peu à peu en remuant sans cesse jusqu'à épaississement.","Parfumez d'un peu de muscade, salez, poivrez et laissez cuire 5 minutes à feu très doux. Réservez.","Préchauffez le four à 200°C (thermostat 6-7). Huilez le plat à lasagnes puis alternez une fine couche de béchamel, des plaques de lasagnes, de la bolognaise, de la béchamel et du parmesan. Répétez l'opération 3 fois.","Sur la dernière couche, ne mettez que de la béchamel, recouvrez de fromage râpé et parsemez de quelques noisettes de beurre.","Enfournez environ 25 minutes et parsemez de basilic frais avant de servir."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Moussaka grecque, pommes de terre et sauce tomate à la cannelle",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:920,p:42,c:70,f:54,prep:110,ing:["boeuf haché","aubergine","pomme de terre","tomate","oignon","huile d'olive","cannelle","miel","beurre","farine","lait"],qty:["250 g","1","3","400 g","1","4 c. à soupe","½ c. à café","1 c. à café","20 g","2 c. à soupe","20 cl"],steps:["Émincez l'oignon et faites-le blondir dans une casserole avec un peu d'huile d'olive.","Ajoutez les tomates coupées en dés, 2 cuillères à soupe d'huile d'olive, la cannelle et le miel. Salez, poivrez et laissez réduire 25 minutes à feu moyen jusqu'à obtenir une sauce.","Coupez les aubergines en rondelles sans les peler, salez-les généreusement et laissez-les dégorger environ 20 minutes, en couches avec du papier absorbant ou dans une passoire.","Épluchez et coupez les pommes de terre en fines rondelles. Disposez-les au fond d'un plat à gratin huilé et arrosez-les de 3 cuillères à soupe du jus de cuisson des tomates.","Passez le plat sous le grill 5 à 15 minutes selon votre four, jusqu'à ce qu'elles dorent.","Épongez les rondelles d'aubergine et faites-les griller quelques minutes de chaque côté à la poêle à feu fort. Réservez.","Dans un faitout, faites revenir la viande hachée à feu assez fort, salez, poivrez et retirez l'excès d'eau rendue par la viande.","Ajoutez la sauce tomate et laissez mijoter à feu très doux.","Préchauffez le four à 200°C (thermostat 6-7).","Préparez la béchamel : faites blondir le beurre dans une casserole, ajoutez la farine et mélangez pour obtenir un appareil homogène. Incorporez peu à peu le lait sans cesser de remuer pendant environ 10 minutes, jusqu'à obtenir une sauce épaisse. Salez, poivrez et râpez un peu de muscade.","Sur la couche de pommes de terre, étalez la moitié de la viande à la tomate, puis la moitié des aubergines, l'autre moitié de viande, l'autre moitié d'aubergines, un filet d'huile d'olive et terminez par la béchamel.","Enfournez à 200°C (thermostat 6-7) pendant 1 heure, jusqu'à ce que la béchamel soit dorée et croustillante."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Filet mignon de porc en croûte au jambon et gruyère",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:900,p:70,c:30,f:53,prep:65,ing:["filet mignon de porc","pâte feuilletée","jambon blanc","gruyère râpé","oignon","jaune d'oeuf"],qty:["400 g","2 pâtes","4 tranches","100 g","1","1"],steps:["Épluchez et émincez l'oignon.","Faites-le revenir dans une sauteuse avec 20 g de beurre pendant 3 minutes, puis réservez-le.","Dans la même sauteuse, faites revenir le filet mignon de chaque côté, puis laissez cuire 10 minutes à feu doux.","Remettez les oignons dans la sauteuse et poursuivez la cuisson 5 minutes. Salez, poivrez et réservez.","Déroulez les pâtes feuilletées. Déposez sur chacune deux tranches de jambon et le gruyère râpé. Salez, poivrez.","Déposez le filet mignon coupé en deux sur chaque pâte garnie et nappez de la sauce aux oignons.","Repliez la pâte autour de la viande et soudez les bords au jaune d'oeuf battu à l'aide d'un pinceau.","Enfournez pour 45 minutes de cuisson à 200°C (thermostat 6-7)."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Sauté de veau au chorizo, tomate et olives vertes",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:680,p:54,c:16,f:43,prep:75,ing:["veau (sauté)","oignon","chorizo","pulpe de tomate","olives vertes","ail"],qty:["400 g","2","100 g","400 g","50 g","1 gousse"],steps:["Émincez l'oignon et coupez le chorizo pelé en rondelles.","Coupez le veau en morceaux.","Faites revenir le veau et l'oignon dans l'huile jusqu'à coloration.","Ajoutez le chorizo, la pulpe de tomate, un peu de basilic haché et l'ail écrasé, puis les olives.","Salez, poivrez, ajoutez un bouquet garni, couvrez et laissez mijoter à feu doux au moins 1 heure.","Ce plat est encore meilleur préparé la veille et réchauffé le jour même."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Boeuf bourguignon à la cocotte-minute, lardons et champignons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:620,p:48,c:10,f:35,prep:75,ing:["boeuf pour bourguignon","lardons","champignons de Paris","oignon","ail","farine","vin rouge","beurre"],qty:["350 g","50 g","100 g","1","1 gousse","1 c. à soupe","25 cl","20 g"],steps:["Hachez l'oignon et pelez l'ail.","Dans une cocotte-minute, faites roussir la viande et les lardons dans le beurre.","Ajoutez l'oignon, les champignons égouttés et saupoudrez de farine. Mélangez et laissez dorer un instant.","Mouillez avec le vin rouge, qui doit recouvrir la viande. Salez, poivrez.","Ajoutez l'ail et un bouquet garni, puis fermez la cocotte-minute.","Laissez cuire doucement 60 minutes à partir de la mise en rotation de la soupape."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Quiche sans pâte, jambon et gruyère",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:410,p:30,c:10,f:28,prep:40,ing:["oeuf","lait","crème fraîche","farine","gruyère râpé","jambon"],qty:["2","25 cl","5 cl","1 c. à soupe","50 g","100 g"],steps:["Mixez les oeufs, le lait, la crème fraîche, la farine et le gruyère râpé. Salez, poivrez.","Coupez le jambon en morceaux et incorporez-le au mélange.","Versez dans un plat à tarte beurré et faites cuire 30 minutes à 200°C."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Hachis parmentier à la tomate et au parmesan",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:550,p:39,c:37,f:27,prep:45,ing:["pomme de terre","viande hachée","oignon","ail","tomate","farine","jaune d'oeuf","parmesan","fromage râpé","beurre"],qty:["400 g","200 g","1","1 gousse","1","1 c. à café","1","15 g","30 g","15 g"],steps:["Épluchez et faites cuire les pommes de terre à l'eau bouillante salée, puis écrasez-les en purée.","Hachez l'oignon et l'ail, et faites-les revenir dans le beurre jusqu'à ce qu'ils soient tendres.","Ajoutez la tomate coupée en dés, la viande hachée et la farine. Salez, poivrez et ajoutez un peu d'herbes de Provence.","Une fois la viande cuite, coupez le feu et incorporez le jaune d'oeuf et le parmesan. Mélangez bien.","Préchauffez le four à 200°C (thermostat 6-7). Étalez la viande au fond d'un plat à gratin, recouvrez de purée, saupoudrez de fromage râpé et faites gratiner."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Gratin dauphinois à l'ail et à la crème fraîche",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:500,p:9,c:50,f:30,prep:80,ing:["pomme de terre","ail","lait","crème fraîche","beurre"],qty:["500 g","1 gousse","30 cl","10 cl","30 g"],steps:["Épluchez, lavez et coupez les pommes de terre en fines rondelles, sans les rincer après les avoir coupées : l'amidon est nécessaire à la bonne tenue du gratin.","Hachez finement l'ail.","Portez à ébullition le lait avec l'ail, du sel, du poivre et de la muscade, puis plongez-y les pommes de terre. Laissez cuire 10 à 15 minutes selon leur fermeté.","Préchauffez le four à 180°C (thermostat 6) et beurrez un plat à gratin.","Égouttez les pommes de terre et disposez-les dans le plat. Recouvrez de crème fraîche et parsemez de noisettes de beurre.","Enfournez pour 50 minutes à 1 heure de cuisson."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Quiche lorraine aux lardons, crème et lait",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:850,p:29,c:30,f:68,prep:65,ing:["pâte brisée","lardons","oeuf","crème fraîche","lait","beurre"],qty:["150 g","100 g","3","10 cl","10 cl","15 g"],steps:["Préchauffez le four à 180°C (thermostat 6). Étalez la pâte dans un moule et piquez-la à la fourchette. Parsemez de copeaux de beurre.","Faites rissoler les lardons à la poêle puis épongez-les sur du papier absorbant.","Battez les oeufs avec la crème fraîche et le lait.","Ajoutez les lardons, puis assaisonnez de sel, de poivre et de muscade.","Versez la préparation sur la pâte et enfournez pour 45 à 50 minutes de cuisson."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Chili con carne mijoté au four",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:610,p:38,c:37,f:33,prep:40,ing:["boeuf haché","oignon","ail","chili en poudre","cumin en poudre","concentré de tomates","haricots rouges","bouillon de boeuf","beurre","persil"],qty:["250 g","1","1 gousse","1 cuillère à café","1 cuillère à café","2 cuillères à soupe","400 g (1 boîte, égouttés)","15 cl","25 g","pour décorer"],steps:["Préchauffez le four à 180°C (thermostat 6).","Hachez l'oignon et l'ail.","Dans une cocotte en fonte, faites fondre le beurre puis faites dorer doucement l'oignon et l'ail.","Ajoutez le boeuf haché et laissez cuire doucement 10 minutes.","Mélangez le chili en poudre, le cumin et le concentré de tomates, puis incorporez ce mélange au boeuf. Ajoutez les haricots rouges et le bouillon de boeuf, salez et poivrez.","Couvrez et laissez cuire 25 minutes au four. Parsemez de persil avant de servir."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Poulet à la moutarde, à l'estragon et aux champignons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:310,p:31,c:6,f:16,prep:35,ing:["blanc de poulet","champignon de Paris","échalote","huile d'olive","moutarde","crème fraîche","estragon","bouillon de volaille"],qty:["2","200 g","2","1 cuillère à soupe","1 cuillère à soupe","2 cuillères à soupe","2 cuillères à café","1 cube (dans 10 cl d'eau)"],steps:["Faites revenir les échalotes émincées dans l'huile d'olive pendant 3 minutes, sans les faire roussir.","Ajoutez les champignons et laissez cuire 2 minutes.","Versez le bouillon de volaille et laissez cuire 10 minutes.","Dans une poêle anti-adhésive, faites revenir les blancs de poulet salés et poivrés jusqu'à ce qu'ils soient dorés.","Ajoutez-les aux champignons et laissez cuire 10 minutes de plus.","Retirez le poulet, puis ajoutez la moutarde, la crème fraîche et l'estragon à la sauce et mélangez bien.","Émincez les blancs de poulet en tranches et servez-les nappés de la sauce aux champignons."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Filet mignon de porc au Maroilles",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:770,p:55,c:6,f:58,prep:40,ing:["filet mignon de porc","oignon","crème fraîche","vin blanc","maroilles"],qty:["1 (environ 450 g)","½","20 cl","5 cl","100 g"],steps:["Hachez l'oignon et faites-le blondir dans une cocotte ou une sauteuse munie d'un couvercle.","Ajoutez le filet mignon et faites-le dorer sur tous les côtés.","Versez le vin blanc, couvrez et laissez cuire 20 minutes.","Pendant ce temps, coupez le Maroilles en petits morceaux et mélangez-le à la crème fraîche dans un bol.","Une fois le filet cuit, ajoutez la crème et le Maroilles dans la cocotte et laissez fondre progressivement en remuant, jusqu'à obtenir une sauce onctueuse. Salez et poivrez.","Servez avec des tagliatelles fraîches."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Carbonades flamandes à la bière brune et au pain d'épices",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:680,p:42,c:32,f:40,prep:200,ing:["boeuf à braiser","lard fumé","oignon","pain d'épices","moutarde","cassonade","bière brune","beurre","bouquet garni"],qty:["500 g","125 g","200 g","3 tranches","2 cuillères à soupe","1 cuillère à soupe","50 cl","15 g","1"],steps:["Coupez la viande en cubes de 2 à 3 cm de côté. Découpez grossièrement les oignons et coupez le lard fumé en gros lardons.","Faites fondre le beurre dans une cocotte et faites suer les oignons à couvert, à feu très doux, pendant 10 minutes pour les ramollir.","Ajoutez le lard en augmentant légèrement le feu et en remuant régulièrement, jusqu'à ce qu'il soit bien rosé. Réservez le mélange lard-oignons dans un plat en conservant le jus dans la cocotte.","Mettez le feu à fond et faites colorer la viande de tous les côtés dans la cocotte, sans couvrir. Réservez la viande en conservant le jus dans la cocotte.","Diluez la cassonade dans le jus de viande et faites réduire de moitié à feu vif.","Baissez le feu au minimum, remettez le mélange lard-oignons dans le jus réduit, ajoutez la viande, le bouquet garni et la bière brune. Salez très légèrement.","Recouvrez toute la surface avec les tranches de pain d'épices tartinées de moutarde.","Laissez mijoter à couvert 3 heures sans remuer, jusqu'à ce que le pain d'épices soit fondu, en retirant le bouquet garni après 1 à 2 heures. Rectifiez l'assaisonnement en cours de cuisson et laissez réduire à découvert en fin de cuisson si la sauce est encore trop liquide."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Couscous poulet et merguez à l'autocuiseur",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:760,p:55,c:60,f:34,prep:70,ing:["pilon de poulet","merguez","pois chiches","carotte","navet","tomate","courgette","concentré de tomates","épices à couscous","harissa","bouillon de boeuf","huile d'olive","semoule fine"],qty:["4","4","150 g (en boîte, égouttés)","2","2","1","1","2 cuillères à soupe","1 cuillère à soupe","1 cuillère à café","1 cube","3 cuillères à soupe","150 g"],steps:["Lavez et épluchez les carottes, les navets et la tomate, puis coupez-les en cubes.","Dans un autocuiseur, versez l'huile d'olive et faites-y dorer les pilons de poulet.","Une fois dorés, ajoutez 1 litre d'eau, le cube de bouillon de boeuf, le concentré de tomates, les carottes, les navets, la tomate, les épices à couscous et la harissa.","Fermez l'autocuiseur et comptez 25 minutes de cuisson une fois la pression atteinte.","Pendant ce temps, lavez et coupez la courgette en cubes, et égouttez les pois chiches.","Évacuez la vapeur, ouvrez l'autocuiseur et ajoutez la courgette et les pois chiches.","Refermez et comptez 10 minutes de cuisson supplémentaires une fois la pression de nouveau atteinte.","Pendant ce temps, faites cuire les merguez à la poêle ou au grill, séparément des légumes.","Préparez la semoule selon les indications du paquet et servez le couscous avec la semoule, le bouillon, les légumes, le poulet et les merguez."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Poulet basquaise au vin blanc",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:760,p:53,c:19,f:50,prep:65,ing:["poulet (morceaux)","tomate","poivron","oignon","ail","vin blanc","huile d'olive","bouquet garni"],qty:["4 morceaux (environ 600 g)","400 g","2 (rouge et vert)","1","1 gousse","10 cl","4 cuillères à soupe","1"],steps:["Hachez l'oignon et l'ail. Coupez les tomates en morceaux et détaillez les poivrons en lanières.","Faites chauffer la moitié de l'huile d'olive dans une cocotte et faites-y dorer l'oignon, l'ail et les poivrons pendant 5 minutes.","Ajoutez les tomates, salez, poivrez, couvrez et laissez mijoter 20 minutes.","Pendant ce temps, dans une sauteuse, faites dorer les morceaux de poulet salés et poivrés dans le reste d'huile d'olive.","Une fois dorés, ajoutez-les aux légumes, couvrez, ajoutez le bouquet garni et le vin blanc.","Laissez cuire encore 35 minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Tarte tatin de légumes",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:760,p:14,c:63,f:49,prep:60,ing:["pâte brisée","oignon","aubergine","courgette","poivron","tomate","parmesan","huile d'olive"],qty:["1 rouleau","1","½","1","1","2","30 g","2 cuillères à soupe"],steps:["Lavez tous les légumes, puis émincez-les.","Faites-les revenir dans l'huile d'olive à feu moyen pendant environ 20 minutes. Aux trois quarts de la cuisson, salez, poivrez et ajoutez un peu d'herbes de Provence si désiré.","Préchauffez le four à 210°C. Garnissez le fond d'un moule à tarte de papier sulfurisé, étalez les légumes par-dessus et tassez-les à la cuillère pour obtenir une surface à peu près plate.","Saupoudrez de parmesan, puis recouvrez de la pâte brisée en rentrant les bords à l'intérieur du moule. Piquez la pâte et enfournez environ 30 minutes, jusqu'à ce qu'elle soit dorée.","À la sortie du four, retournez la tarte sur un plat de service et dégustez chaude."],diet:{vegetarien:true,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Parmentier de confit de canard",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:880,p:51,c:56,f:49,prep:70,ing:["cuisse de canard confite","pomme de terre","oignon","échalote","crème fraîche","lait","muscade"],qty:["2","5 (bintje)","1","1","1 cuillère à soupe","10 cl","1 pincée"],steps:["Lavez et épluchez les pommes de terre, puis faites-les cuire dans un grand volume d'eau salée.","Réchauffez les cuisses de canard au bain-marie pour les débarrasser de leur graisse ; réservez 1 cuillère à soupe de graisse de canard.","Découpez et hachez grossièrement la chair des cuisses confites, sans les mixer.","Émincez l'échalote et l'oignon.","Dans une large poêle, faites blondir l'oignon et l'échalote dans la graisse de canard réservée, à feu très doux.","Une fois bien blonds, ajoutez le hachis de canard et faites revenir à feu vif pendant 5 minutes en mélangeant vivement, jusqu'à ce qu'il soit légèrement grillé en surface mais resté moelleux. Réservez hors du feu.","Écrasez les pommes de terre à la fourchette et préparez une purée moelleuse en ajoutant le lait et un peu d'eau de cuisson.","Salez, poivrez, ajoutez la muscade et la crème fraîche.","Préchauffez le four à 200°C (thermostat 6-7).","Dans un plat, étalez la moitié du hachis de canard. Mélangez le reste avec autant de purée et étalez cette couche sur la première, puis terminez par une dernière couche de purée.","Striez le sommet avec le dos d'une fourchette et enfournez 25 minutes, en terminant éventuellement 3 minutes sous le gril pour gratiner."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Lapin à la moutarde et au vin blanc",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:950,p:70,c:12,f:63,prep:80,ing:["lapin","vin blanc sec","échalote","ail","crème fraîche","moutarde de Dijon","laurier","thym","carotte","persil","huile d'olive"],qty:["1 (coupé en morceaux, environ 1,2 kg)","50 cl","4","3 gousses","30 cl","2 cuillères à soupe","4 feuilles","2 branches","2","1 bouquet","2 cuillères à soupe"],steps:["Coupez le lapin en morceaux et badigeonnez-les légèrement de moutarde. Faites-les revenir dans l'huile d'olive sans les faire brûler, puis réservez.","Pendant ce temps, portez à ébullition le vin blanc avec l'ail émincé, le laurier, le thym et les carottes coupées en rondelles.","Dans la cocotte, faites dorer les échalotes émincées, ajoutez le lapin puis versez le vin blanc chaud par-dessus. Salez, poivrez et laissez cuire à feu doux pendant 1 heure.","Dans un bol, mélangez la crème fraîche, le persil haché et le reste de moutarde.","En fin de cuisson, disposez les morceaux de lapin sur un plat de service et saupoudrez de persil.","Filtrez le jus de cuisson si désiré, puis incorporez la crème à la moutarde. Faites chauffer 1 minute sans laisser bouillir, et nappez le lapin de cette sauce avant de servir."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Chili con carne aux haricots rouges",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:580,p:43,c:35,f:30,prep:30,ing:["oignon","ail","viande hachée","haricots rouges en boîte","tomates pelées en boîte","piment chili en poudre","huile d'olive"],qty:["1","1 gousse","300 g","300 g","300 g","1 cuillère à café","1 cuillère à soupe"],steps:["Hacher l'oignon et l'ail.","Faire chauffer l'huile d'olive dans une cocotte et y faire fondre l'oignon et l'ail.","Ajouter la viande hachée et la laisser colorer.","Saupoudrer de piment chili selon le goût.","Égoutter les haricots rouges et les ajouter dans la cocotte avec les tomates pelées.","Saler, poivrer, mélanger et laisser mijoter 20 minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Boeuf braisé aux carottes et aux lardons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:540,p:51,c:14,f:29,prep:105,ing:["boeuf à braiser (paleron ou bourguignon)","lardons","oignon","carotte","ail","concentré de tomates","cube de bouillon de boeuf"],qty:["350 g","50 g","1","2","1 gousse","1 cuillère à soupe","1"],steps:["Couper la viande en morceaux égaux et la faire revenir dans une cocotte en fonte avec un peu de matière grasse chaude.","Une fois les morceaux bien dorés sur toutes les faces, les retirer et faire revenir l'oignon émincé et les lardons.","Préparer le bouillon en diluant le cube de bouillon de boeuf dans 50 cl d'eau chaude.","Remettre la viande dans la cocotte, verser le bouillon, ajouter le concentré de tomates, les carottes épluchées et coupées en tronçons, l'ail écrasé, un peu de thym, de laurier et de sauge.","Saler, poivrer, mélanger et laisser mijoter 1h30 à feu doux."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Endives au jambon gratinées au gruyère",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:620,p:23,c:10,f:53,prep:50,ing:["endive","jambon","crème fraîche","gruyère râpé","ail","beurre"],qty:["500 g","2 tranches","20 cl","100 g","2 gousses","1 noisette"],steps:["Effeuiller les endives et les faire cuire dans l'eau bouillante jusqu'à ce qu'elles soient tendres, puis les égoutter.","Faire fondre le beurre dans une casserole, ajouter l'ail écrasé puis la crème fraîche. Saler, poivrer et incorporer la majeure partie du gruyère râpé en réservant le reste pour le gratin.","Dans un plat allant au four, alterner une couche d'endives, une couche de jambon puis une couche de sauce à la crème ; renouveler l'opération et terminer par le reste de gruyère râpé.","Faire gratiner environ 30 minutes à four chaud (200°C)."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Ratatouille provençale mijotée",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:330,p:4,c:26,f:22,prep:80,ing:["tomate","aubergine","courgette","poivron (rouge et vert)","oignon","ail","huile d'olive"],qty:["300 g","200 g","200 g","200 g","200 g","2 gousses","3 cuillères à soupe"],steps:["Couper les tomates pelées en quartiers, les aubergines et les courgettes en rondelles, émincer les poivrons en lamelles et l'oignon en rouelles.","Chauffer 2 cuillères à soupe d'huile d'olive dans une poêle et faire fondre l'oignon et les poivrons.","Lorsqu'ils sont tendres, ajouter les tomates, l'ail haché, un brin de thym et une feuille de laurier. Saler, poivrer et laisser mijoter à couvert 45 minutes.","Pendant ce temps, faire cuire les aubergines et les courgettes dans le reste d'huile d'olive pendant 15 minutes.","Vérifier la cuisson des légumes et les ajouter au mélange de tomates. Prolonger la cuisson à feu très doux pendant 10 minutes.","Rectifier l'assaisonnement si besoin."],diet:{vegetarien:true,vegan:true,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Filet mignon de porc à la moutarde à l'ancienne et aux champignons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:670,p:41,c:6,f:50,prep:40,ing:["filet mignon de porc","champignons en boîte","crème fraîche","vin blanc sec","moutarde à l'ancienne","beurre","cube de bouillon de légumes"],qty:["350 g","250 g","20 cl","15 cl","2 cuillères à soupe","20 g","1/2"],steps:["Couper la viande en morceaux et faire chauffer un mélange d'huile d'olive et de beurre dans une cocotte.","Faire dorer la viande sur toutes les faces, puis la retirer et jeter le surplus de gras.","Déglacer la cocotte avec le vin blanc, le demi-cube de bouillon émietté, le jus des champignons et les deux tiers de la crème fraîche.","Tartiner le filet mignon de moutarde à l'ancienne et le remettre dans la cocotte avec les champignons.","Laisser cuire environ 30 minutes à feu très doux.","En fin de cuisson, ajouter le reste de crème fraîche, saler et poivrer."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Crevettes au curry et à la crème",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:240,p:30,c:2,f:12,prep:10,ing:["crevettes roses","crème fraîche","curry","huile d'olive"],qty:["300 g","2 cuillères à soupe","1 cuillère à café","2 cuillères à café"],steps:["Décortiquer les crevettes.","Les faire revenir très rapidement dans l'huile d'olive en les saupoudrant de curry.","Ajouter la crème fraîche et mélanger.","Servir immédiatement avec du riz thaï."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Paupiettes de veau au vinaigre balsamique et à la moutarde",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:520,p:45,c:5,f:30,prep:35,ing:["paupiette de veau","fond de veau","moutarde de Dijon","vinaigre balsamique","vin blanc","ail","huile d'olive"],qty:["4","2 cuillères à soupe","1 cuillère à soupe","1 cuillère à soupe","15 cl","1 gousse","1 cuillère à soupe"],steps:["Faire chauffer l'huile d'olive avec l'ail finement haché dans une sauteuse, à feu moyen.","Faire dorer les paupiettes de veau quelques minutes de chaque côté.","Ajouter le fond de veau et mouiller avec le vin blanc et un peu d'eau.","Incorporer la moutarde et le vinaigre balsamique, bien mélanger en retournant les paupiettes pour qu'elles s'imprègnent de la sauce.","Laisser cuire 5 minutes à feu moyen pour évaporer l'alcool, puis couvrir et laisser mijoter environ 20 minutes à feu doux, en retournant de temps en temps.","Servir avec des légumes ou des féculents au choix."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Tartiflette aux lardons fumés et reblochon",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:850,p:38,c:48,f:57,prep:40,ing:["pomme de terre","lardons fumés","oignon","reblochon","ail","huile"],qty:["500 g","100 g","100 g","1/2","1 gousse","1 cuillère à soupe"],steps:["Éplucher les pommes de terre, les couper en dés, les rincer et les essuyer.","Faire chauffer l'huile dans une poêle et faire fondre les oignons.","Ajouter les pommes de terre et les faire dorer de tous les côtés.","Ajouter les lardons et finir de cuire, puis éponger le surplus de gras avec du papier absorbant.","Gratter la croûte du reblochon et le couper en deux.","Préchauffer le four à 200°C et frotter un plat à gratin avec la gousse d'ail épluchée.","Étaler une couche de pommes de terre aux lardons, disposer la moitié du reblochon, ajouter une nouvelle couche de pommes de terre puis terminer avec le reste du reblochon, croûte vers le haut.","Enfourner environ 20 minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Rôti de porc à la moutarde de Dijon et aux échalotes",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:540,p:57,c:11,f:29,prep:105,ing:["rôti de porc","échalote","ail","moutarde de Dijon","crème fraîche allégée"],qty:["400 g","4","1 gousse","2 cuillères à soupe","10 cl"],steps:["Piquer le rôti de petites pointes d'ail.","Le faire dorer sur toutes les faces dans une cocotte avec un peu de beurre. Saler et poivrer.","Retirer le rôti, le badigeonner de moutarde de Dijon forte, puis le remettre dans la cocotte avec les échalotes.","Couvrir et laisser mijoter à feu doux environ 1h30, en retournant de temps en temps et en ajoutant un peu d'eau si le liquide s'évapore.","Retirer le rôti et les échalotes, rectifier l'assaisonnement de la sauce puis ajouter la crème fraîche allégée.","Couper le rôti en tranches et servir nappé de sauce, avec les échalotes entières."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Tajine d'agneau aux pruneaux et aux amandes",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:750,p:48,c:42,f:42,prep:100,ing:["épaule d'agneau","oignon","pruneaux","amandes émondées","ail","miel","gingembre","cannelle","safran","huile d'olive"],qty:["500 g","2","200 g","40 g","1 gousse","1 cuillère à soupe","1/2 cuillère à café","1/2 cuillère à café","1 dosette","2 cuillères à soupe"],steps:["Faire tremper les pruneaux dans du thé chaud.","Faire revenir les oignons émincés dans l'huile d'olive ; une fois dorés, les retirer et remplacer par la viande d'agneau.","Lorsque les morceaux sont bien dorés, les mettre dans une cocotte avec les oignons. Saler, poivrer, ajouter l'ail écrasé, la cannelle, le gingembre, le safran et quelques graines de coriandre écrasées.","Couvrir d'eau et laisser cuire 1 heure à feu doux.","Ajouter les pruneaux égouttés et poursuivre la cuisson 20 minutes à couvert.","Faire revenir les amandes dans un peu de beurre chaud, les égoutter puis les ajouter à la viande avec le miel.","Laisser cuire encore 5 minutes sans couvrir, puis servir avec de la semoule de couscous."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:false}},
{n:"Filet de poulet mariné au curry, sauce soja et ciboulette",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:380,p:30,c:8,f:24,prep:80,ing:["oignon","curry","crème fraîche","filet de poulet","sauce soja","ciboulette"],qty:["1/2","1/2 cuillère à café","5 cl","2","2 cuillères à soupe","2 brins"],steps:["Couper les filets de poulet en petits morceaux et les mettre dans un saladier avec la sauce soja, un peu d'ail en poudre, un filet d'huile d'olive, la ciboulette ciselée et le curry. Laisser mariner environ 1 heure.","Faire revenir l'oignon émincé dans un peu d'huile d'olive jusqu'à légère caramélisation, puis ajouter la viande marinée.","Quand la viande commence à cuire, incorporer petit à petit la crème fraîche et ajuster la quantité de curry selon le goût.","Bien mélanger, saler et poivrer, puis servir chaud."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Blanc de poulet aux endives, champignons et lardons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:480,p:32,c:8,f:34,prep:40,ing:["lardons fumés","beurre","oignon","crème fraîche","cognac","farine","blanc de poulet","endive","champignons de Paris"],qty:["100 g","20 g","1/2","2 cuillères à soupe","1/2 cuillère à soupe","1/2 cuillère à soupe","2","1","200 g"],steps:["Couper les blancs de poulet en fines lamelles et les fariner légèrement.","Faire fondre le beurre dans une poêle et y dorer les lamelles de poulet. Saler, poivrer, déglacer au cognac, puis réserver.","Dans la même poêle, faire revenir les lardons, ajouter l'oignon émincé et l'endive coupée en petits morceaux, et laisser mijoter environ 5 minutes.","Ajouter les champignons de Paris et laisser mijoter 5 minutes de plus.","Remettre le poulet dans la poêle, couvrir et laisser mijoter environ 20 minutes, en ajoutant la crème fraîche au bout de 15 minutes.","Parsemer de persil ciselé juste avant de servir."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Poulet au curry, cumin et piment",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:280,p:33,c:4,f:13,prep:25,ing:["oignon jaune","curry","cumin","piment","blanc de poulet","crème fraîche allégée"],qty:["1","1 cuillère à café","1/2 cuillère à café","1 pincée","2","10 cl"],steps:["Émincer l'oignon et le faire revenir à feu vif dans une grande poêle.","Ajouter le curry et le cumin, bien mélanger.","Couper les blancs de poulet en morceaux, les ajouter dans la poêle avec le piment, et remuer.","Baisser le feu et ajouter la moitié de la crème fraîche allégée.","Laisser cuire 5 minutes, puis ajouter le reste de crème et rectifier les épices selon le goût. Saler et poivrer.","Si le plat est préparé à l'avance, ajouter un peu de crème au moment de réchauffer car la sauce a tendance à s'évaporer."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Lasagnes à la bolognaise et à la béchamel au gruyère",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:700,p:38,c:45,f:40,prep:80,ing:["pâtes à lasagnes","viande hachée","sauce bolognaise","oignon","beurre","farine","lait","gruyère râpé"],qty:["6 feuilles","300 g","300 g","1","50 g","2 cuillères à soupe","25 cl","50 g"],steps:["Émincer l'oignon et le faire revenir dans un peu d'huile d'olive jusqu'à ce qu'il soit bien doré.","Ajouter la viande hachée, faire cuire à feu moyen, puis incorporer la sauce bolognaise.","Préparer la béchamel : faire fondre le beurre à feu vif, ajouter la farine et fouetter à feu moyen jusqu'à obtenir un mélange homogène.","Verser progressivement le lait sans cesser de fouetter, pour éviter les grumeaux, et laisser épaissir.","Mélanger la béchamel avec la sauce bolognaise préparée.","Dans un plat à gratin, alterner une couche de sauce et une couche de pâtes à lasagnes, jusqu'à épuisement de la préparation, en terminant par une couche de sauce.","Parsemer de gruyère râpé et enfourner environ 45 minutes à 180°C (thermostat 6), jusqu'à ce que les pâtes soient fondantes (vérifier avec la pointe d'un couteau)."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Tajine de poulet aux raisins secs, pois chiches et citron",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:520,p:34,c:46,f:22,prep:70,ing:["oignon","gingembre","pois chiches","cumin","safran","miel","cuisse de poulet","ail","tomate","paprika","mélange 4 épices","cannelle","bouillon de volaille","citron","raisins secs"],qty:["1/2","1/4 cuillère à café","200 g","1/2 cuillère à café","1/2 cuillère à café","1 cuillère à soupe","2","1 gousse","1","1/2 cuillère à café","1/2 cuillère à café","1/2 cuillère à café","25 cl","1/2","50 g"],steps:["Mélanger dans un bol le gingembre, le cumin, le safran, le paprika, le mélange 4 épices, la cannelle et l'ail haché.","Dans un autre bol, mélanger les dés de tomate, les dés de citron et le miel.","Retirer la peau des cuisses de poulet et les faire dorer dans une cocotte chaude avec un peu d'huile d'olive, puis les réserver.","Faire revenir l'oignon émincé dans la même cocotte, remettre les cuisses de poulet, ajouter le mélange d'épices puis le mélange tomate-citron-miel.","Verser le bouillon de volaille jusqu'à bien couvrir les cuisses de poulet. Saler, poivrer et ajouter un trait de tabasco selon le goût.","Ajouter les raisins secs et les pois chiches. Porter à ébullition, puis baisser le feu et laisser mijoter environ 45 minutes. Servir avec de la semoule fine."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Rôti de porc glacé au miel et à la moutarde",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:440,p:44,c:12,f:24,prep:105,ing:["oignon","moutarde de Dijon","miel","rôti de porc","ail","bouillon de volaille"],qty:["2","1 cuillère à soupe","1 cuillère à soupe","400 g","1 gousse","10 cl"],steps:["Préchauffer le four à 180°C (thermostat 6).","Mélanger la moutarde, le miel, l'ail et un peu de bouillon de volaille dans un bol. Saler et poivrer.","Badigeonner le rôti de porc de cette préparation et le poser sur les rondelles d'oignon dans un plat allant au four.","Verser le reste du bouillon, couvrir le rôti et enfourner environ 1h30.","Vérifier la cuisson en piquant le rôti avec un cure-dent : s'il pénètre facilement, le rôti est cuit."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Rougail saucisse",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:580,p:28,c:8,f:47,prep:50,ing:["oignon","tomate en conserve","saucisse fumée","ail","curcuma","piment oiseau"],qty:["2","2","4","3 gousses","1/2 cuillère à café","1/2 (facultatif)"],steps:["Piquer les saucisses et les plonger dans l'eau bouillante pendant 10 minutes, dans la marmite qui servira ensuite à la préparation du plat.","Vider la marmite, réserver les saucisses, puis faire chauffer un peu d'huile d'olive dedans.","Faire revenir les oignons émincés et l'ail écrasé sans trop les colorer.","Couper les saucisses en tronçons d'environ 1,5 cm et les ajouter aux oignons. Au bout de 5 minutes, ajouter les tomates coupées en morceaux, le curcuma, un peu de thym, une feuille de laurier et le piment oiseau émietté si désiré.","Mélanger, saler, poivrer, puis laisser mijoter à feu doux en retirant le couvercle de temps en temps pour réduire l'excès d'eau.","Servir avec du riz thaï."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Osso bucco de veau au vin blanc et tomates",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:350,p:42,c:14,f:14,prep:65,ing:["oignon","carotte","tomates concassées","jarret de veau","ail","vin blanc sec"],qty:["2","100 g","200 g","400 g","2 gousses","10 cl"],steps:["Fariner légèrement la viande et tapoter pour retirer l'excédent. Faire dorer les tranches de jarret de veau sur toutes les faces dans une cocotte-minute avec un peu d'huile.","Peler et couper les carottes en rondelles épaisses, émincer les oignons et hacher l'ail. Les ajouter dans la cocotte avec les tomates concassées et le vin blanc.","Saler, poivrer, ajouter un bouquet garni et fermer la cocotte.","Laisser cuire environ 45 minutes à feu doux à partir de la mise en rotation de la soupape."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Quiche aux poireaux, chèvre et lardons",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:850,p:30,c:45,f:58,prep:40,ing:["lardons fumés","poireau","crème fraîche","pâte brisée","fromage de chèvre","oeuf","lait"],qty:["100 g","2","10 cl","1","100 g","2","5 cl"],steps:["Préchauffer le four à 180°C (thermostat 6). Étaler la pâte brisée dans un moule beurré et fariné.","Nettoyer et émincer le blanc des poireaux.","Faire dorer les lardons dans une poêle, puis faire revenir les poireaux dans la graisse rendue.","Répartir les lardons et les poireaux sur le fond de tarte.","Battre les oeufs avec la crème fraîche et le lait, assaisonner puis verser le mélange sur la garniture.","Découper le fromage de chèvre en rondelles et les déposer sur la quiche.","Cuire au four de 25 à 30 minutes."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Sauté de veau au porto, chorizo et olives noires",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:540,p:42,c:30,f:24,prep:75,ing:["porto","oignon","sauté de veau","chorizo","pomme de terre","olive noire","concentré de tomates","ail"],qty:["15 cl","1","300 g","1 morceau (10 cm)","2","1 poignée","2 cuillères à soupe","1 gousse"],steps:["Couper la viande en gros cubes et la faire revenir dans une cocotte avec un peu d'huile d'olive pendant quelques minutes.","Ajouter l'oignon émincé et le faire roussir.","Ajouter un peu d'eau et le porto, puis délayer le concentré de tomates dedans.","Ajouter le chorizo coupé en fines rondelles, les pommes de terre en gros morceaux, les olives noires, l'ail et une pincée de thym. Saler modérément et poivrer.","Laisser mijoter environ 1 heure, en rajoutant un peu d'eau si la sauce réduit trop.","Ce plat est encore meilleur réchauffé le lendemain ; ne pas supprimer le chorizo ni le porto, qui donnent tout leur caractère à la recette."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:true,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Blanquette de veau aux champignons et au citron",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:520,p:35,c:18,f:33,prep:120,ing:["épaule de veau","poireau","carotte","oignon","échalote","ail","céleri branche","champignons de Paris","farine","beurre","crème fraîche","jaune d'oeuf","vin blanc sec","citron"],qty:["400 g","1","1","1","1","1 gousse","1 branche","100 g","1 cuillère à soupe","25 g","10 cl","1","1 cuillère à soupe","1/2"],steps:["Éplucher la carotte, l'ail, l'échalote et l'oignon ; hacher l'oignon et les blancs de poireau, couper l'échalote et la carotte en deux.","Porter à ébullition 2 litres d'eau dans un faitout et y plonger les morceaux de veau pendant 1 minute pour les blanchir ; égoutter, rincer sous l'eau froide et jeter l'eau de cuisson.","Remettre la viande dans le faitout rincé, ajouter l'oignon et le poireau hachés, la carotte, l'échalote, l'ail, le céleri et un bouquet garni. Saler, poivrer, mouiller avec le vin blanc et ajouter de l'eau à hauteur.","Couvrir, porter à ébullition et laisser cuire 1 h 30. Pendant ce temps, faire revenir les champignons émincés et citronnés dans une poêle avec un peu de beurre pendant 10 minutes.","Préparer un roux : faire fondre le reste du beurre dans une casserole, ajouter la farine et mélanger vivement au fouet, puis laisser refroidir. Égoutter la viande et les légumes en récupérant le bouillon de cuisson, puis délayer le roux avec ce bouillon et porter à ébullition en fouettant.","Remettre la viande et les légumes dans le faitout après avoir retiré le bouquet garni, l'ail et le céleri. Ajouter les champignons, verser la sauce et réchauffer 10 à 15 minutes.","Juste avant de servir, mélanger la crème fraîche et le jaune d'oeuf et les incorporer hors du feu à la sauce sans laisser bouillir. Ajouter quelques gouttes de jus de citron et servir avec du persil ciselé."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:false,sans_fruits_a_coque:true}},
{n:"Filet mignon de porc aux courgettes et raisins secs",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:460,p:46,c:20,f:22,prep:40,ing:["filet mignon de porc","courgette","raisins secs","ail","bouillon de volaille","huile d'olive","beurre"],qty:["400 g","500 g","40 g","1 gousse","10 cl","1 cuillère à soupe","15 g"],steps:["Éplucher les courgettes et les couper en tronçons ou en gros bâtonnets de 5 cm de long.","Faire revenir le filet mignon dans une cocotte avec l'huile d'olive et le beurre jusqu'à ce qu'il soit bien doré.","Ajouter les courgettes, l'ail écrasé, les raisins secs et le bouillon de volaille dégraissé, avec un bouquet garni. Saler et poivrer.","Bien mélanger, couvrir et laisser cuire 25 minutes à feu doux.","Découper le filet mignon en tranches fines, le dresser sur un plat entouré de la garniture de courgettes et raisins, et servir avec de la semoule de couscous cuite à la vapeur."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Tartiflette au jambon fumé",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:640,p:40,c:34,f:38,prep:60,ing:["pomme de terre","oignon","jambon fumé","reblochon","vin blanc sec"],qty:["400 g","1","120 g","1/2","10 cl"],steps:["Faire cuire les pommes de terre avec leur peau, puis les éplucher et les couper en rondelles.","Émincer l'oignon et le faire revenir dans un peu de beurre jusqu'à ce qu'il soit doré.","Ajouter le jambon fumé coupé en dés puis les pommes de terre et laisser mijoter 15 minutes.","Verser le vin blanc, saler légèrement, poivrer et laisser les pommes de terre s'imprégner quelques minutes avant de transférer le tout dans un plat à gratin.","Gratter la croûte du reblochon au couteau, le couper en deux dans l'épaisseur et le poser sur les pommes de terre.","Faire cuire à four chaud (220°C) pendant 20 à 30 minutes et servir avec une salade verte."],diet:{vegetarien:false,vegan:false,sans_poisson:true,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
{n:"Papillote de saumon à la mozzarella et aux tomates",cat:"déjeuner/dîner",tags:["classique","equilibre"],kcal:580,p:44,c:6,f:42,prep:50,ing:["saumon","tomate","mozzarella","ail","olives noires","huile d'olive"],qty:["2 pavés","2","1 boule","2 gousses","2","4 cuillères à café"],steps:["Poser chaque pavé de saumon sur une feuille de papier aluminium séparée, saler et poivrer légèrement.","Couper les tomates et la mozzarella en fines tranches et les disposer en alternance sur le saumon (tomate, mozzarella, tomate...).","Émincer les olives et l'ail, en parsemer les pavés, ajouter un peu de sel, de poivre, une pincée d'herbes de Provence et un peu de basilic ciselé.","Arroser chaque pavé de 2 cuillères à café d'huile d'olive, refermer hermétiquement chaque papillote et les disposer dans un plat à gratin.","Cuire à four chaud (210°C, th.7) pendant 35 minutes, jusqu'à ce que la peau du saumon soit bien claire.","Servir avec du riz basmati et une salade verte parsemée d'oignon."],diet:{vegetarien:false,vegan:false,sans_poisson:false,sans_lactose:false,sans_gluten:true,sans_fruits_a_coque:true}},
];
